import { mkdir, open } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';

const DAILY_CAP = 2;
const CHANNELS = new Set(['sms', 'email', 'push']);

// Local calendar day (YYYY-MM-DD) of `now` in the given IANA time zone.
function localDay(now, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    calendar: 'gregory',
    numberingSystem: 'latn',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

// Each allowed message claims one numbered slot file for (user, local day) with
// O_EXCL ('wx'). Creation is atomic across processes, so no lock is needed, a
// crashed worker cannot leave a stale lock, and the count survives restarts.
export async function reserve({ userId, timeZone, channel, now }) {
  if (typeof userId !== 'string' || userId === '') throw new TypeError('userId must be a non-empty string');
  if (!CHANNELS.has(channel)) throw new TypeError(`unknown channel: ${channel}`);
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) throw new TypeError('now must be a valid Date');
  const stateDir = process.env.STATE_DIR;
  if (!stateDir) throw new Error('STATE_DIR is not set');

  const day = localDay(now, timeZone); // throws RangeError on an invalid time zone
  const userKey = createHash('sha256').update(userId).digest('hex');
  const dir = path.join(stateDir, 'marketing', userKey, day);
  await mkdir(dir, { recursive: true });

  for (let slot = 1; slot <= DAILY_CAP; slot++) {
    let fh;
    try {
      fh = await open(path.join(dir, `slot-${slot}`), 'wx');
    } catch (err) {
      if (err.code === 'EEXIST') continue;
      throw err;
    }
    try {
      await fh.writeFile(JSON.stringify({ userId, timeZone, channel, at: now.toISOString() }) + '\n');
    } finally {
      await fh.close();
    }
    return { allowed: true, rule: '' };
  }
  return { allowed: false, rule: 'daily-cap' };
}

import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert';

const BOT = process.argv[2];
if (process.argv[3] === 'child') {
  const { reserve } = await import(BOT);
  const [user, tz, iso, n] = process.argv.slice(4);
  const rs = await Promise.all(Array.from({ length: +n }, () => reserve({ userId: user, timeZone: tz, channel: 'sms', now: new Date(iso) })));
  console.log(JSON.stringify(rs.filter((r) => r.allowed).length));
  process.exit(0);
}
const dir = mkdtempSync(path.join(os.tmpdir(), 'st-'));
const run = (user, tz, iso, n) => new Promise((res) => {
  const c = spawn('node', [process.argv[1], BOT, 'child', user, tz, iso, String(n)], { env: { ...process.env, STATE_DIR: dir } });
  let o = ''; c.stdout.on('data', (d) => (o += d)); c.on('close', () => res(+o));
});
// 8 processes x 5 concurrent calls, same user
let total = (await Promise.all(Array.from({ length: 8 }, () => run('u1', 'Asia/Tokyo', '2026-10-23T01:00:00Z', 5)))).reduce((a, b) => a + b);
assert.equal(total, 2);
// after restart (new processes) still capped
assert.equal(await run('u1', 'Asia/Tokyo', '2026-10-23T05:00:00Z', 3), 0);
// 14:59Z = 23:59 Tokyo same day; 15:00Z = next Tokyo day
assert.equal(await run('u1', 'Asia/Tokyo', '2026-10-23T14:59:59Z', 1), 0);
assert.equal(await run('u1', 'Asia/Tokyo', '2026-10-23T15:00:00Z', 5), 2);
// same instant in New York is a different day with own count
assert.equal(await run('u1', 'America/New_York', '2026-10-23T15:00:00Z', 5), 2);
// different user independent
assert.equal(await run('u2', 'Asia/Tokyo', '2026-10-23T01:00:00Z', 5), 2);
console.log('ok');

